mkdir -p ~/academy-labs/g7-6 && cd ~/academy-labs/g7-6 && git init -q -b main
cat > server.mjs <<'EOF'
import { createServer } from "node:http";

const projects = []; // the seed data: the workgroup "Lab A" exists and has no projects yet

createServer(async (req, res) => {
  if (req.method === "POST" && req.url === "/projects") {
    let body = "";
    for await (const chunk of req) body += chunk;
    projects.push(JSON.parse(body));
    res.writeHead(201).end();
    return;
  }
  res.writeHead(200, { "content-type": "application/json" }).end(JSON.stringify(projects));
}).listen(8080);
EOF
cat > smoke.mjs <<'EOF'
// The smoke test: a fresh workgroup shows the empty card, and one new project makes a list of one.
const api = "http://api:8080/projects";
const list = async () => (await fetch(api)).json();
const fail = (message) => {
  console.log(`FAIL  run ${process.env.RUN}: ${message}`);
  process.exit(1);
};

if ((await list()).length !== 0) fail("the workgroup is not empty, so the No projects yet card cannot show");
await fetch(api, { method: "POST", body: JSON.stringify({ name: `Lung CT ${process.env.RUN}` }) });
await new Promise((resolve) => setTimeout(resolve, 2000)); // a real smoke suite takes minutes, not milliseconds
const after = await list();
if (after.length !== 1) fail(`expected 1 project, found ${after.length}: ${after.map((p) => p.name).join(", ")}`);
console.log(`pass  run ${process.env.RUN}: empty card, then one project`);
EOF
cat > Dockerfile <<'EOF'
FROM node:24-alpine
WORKDIR /app
COPY server.mjs smoke.mjs ./
CMD ["node", "server.mjs"]
EOF
cat > compose.yaml <<'EOF'
services:
  api:
    image: lab-api:${TAG:?set TAG to the commit}
    healthcheck:
      test: ["CMD", "wget", "-qO-", "http://localhost:8080/projects"]
      interval: 1s
      retries: 20
  smoke:
    image: lab-api:${TAG:?set TAG to the commit}
    command: ["node", "smoke.mjs"]
    depends_on:
      api: { condition: service_healthy }
    profiles: [test]
EOF
git add -A && git commit -qm "lab stack" && git log --oneline

export TAG=$(git rev-parse --short HEAD)
docker compose -p qa up -d --wait 2>/dev/null
docker compose -p qa run --rm -e RUN=A smoke 2>/dev/null; docker compose -p qa run --rm -e RUN=B smoke 2>/dev/null
